mapper.select:
SELECT p.property_id AS propertyId, p.address AS title, p.building_type AS buildingType, p.room_type AS roomType, p.deposit AS deposit, p.monthly_rent AS monthlyRent, p.area AS area, p.floor AS floor, p.built_year AS builtYear, p.is_illegal_building AS isIllegalBuilding, CASE WHEN p.is_illegal_building = TRUE THEN '건축물대장 상 무단 증·개축 위반 지정' ELSE '건축물대장 표제부 기준 적법 건물 (무단 증·개축 없음)' END AS illegalReason, CONCAT(p.built_year, '1015') AS useAprDay, '철근콘크리트구조' AS structureName, CASE WHEN p.building_type = 3 THEN '업무시설(오피스텔)' ELSE '공동주택(다세대/연립)' END AS mainPurposeName, '1' AS earthquakeProofYn, p.address AS address, p.property_latitude AS latitude, p.property_longitude AS longitude, NULL AS thumbnailUrl, COALESCE(ps.safety_score, 85) AS safetyScore, CASE WHEN COALESCE(ps.safety_score, 85) >= 80 THEN 'SAFE' WHEN COALESCE(ps.safety_score, 85) >= 60 THEN 'WARNING' ELSE 'DANGER' END AS safetyGrade, COALESCE(p.deal_count, 1) AS dealCount, CASE WHEN b.user_id IS NOT NULL THEN TRUE ELSE FALSE END AS isBookmarked FROM properties p LEFT JOIN property_safety ps ON p.property_id = ps.property_id AND ps.destination_id =
#{cond.destinationId}
-1
LEFT JOIN bookmarks b ON p.property_id = b.property_id
AND b.user_id = #{userId}
WHERE p.del_yn = 'N'
AND p.address LIKE CONCAT('%', #{cond.keyword}, '%')
AND p.building_type = #{cond.buildingType}
AND p.room_type = #{cond.roomType}
AND p.deposit >= #{cond.minDeposit}
AND p.deposit <= #{cond.maxDeposit}
AND p.monthly_rent >= #{cond.minMonthlyRent}
AND p.monthly_rent <= #{cond.maxMonthlyRent}
AND p.property_latitude BETWEEN #{cond.swLat} AND #{cond.neLat} AND p.property_longitude BETWEEN #{cond.swLng} AND #{cond.neLng}
AND p.property_latitude BETWEEN (#{cond.lat} - (#{cond.radius} / 111.0)) AND (#{cond.lat} + (#{cond.radius} / 111.0)) AND p.property_longitude BETWEEN (#{cond.lng} - (#{cond.radius} / 88.0)) AND (#{cond.lng} + (#{cond.radius} / 88.0)) AND (6371 * acos(cos(radians(#{cond.lat})) * cos(radians(p.property_latitude)) * cos(radians(p.property_longitude) - radians(#{cond.lng})) + sin(radians(#{cond.lat})) * sin(radians(p.property_latitude)))) <= #{cond.radius}
ORDER BY p.deposit ASC, p.monthly_rent ASC
ORDER BY p.deposit DESC, p.monthly_rent DESC
ORDER BY ps.safety_score DESC
ORDER BY p.area DESC
ORDER BY (6371 * acos(cos(radians(#{cond.lat})) * cos(radians(p.property_latitude)) * cos(radians(p.property_longitude) - radians(#{cond.lng})) + sin(radians(#{cond.lat})) * sin(radians(p.property_latitude)))) ASC
ORDER BY p.property_id DESC
LIMIT 500

SELECT p.property_id AS propertyId, p.address AS title, CONCAT(p.address, ' 위치의 안심 주거 매물입니다.') AS description, p.building_type AS buildingType, p.room_type AS roomType, p.deposit AS deposit, p.monthly_rent AS monthlyRent, p.area AS area, p.floor AS floor, p.built_year AS builtYear, p.address AS address, p.property_latitude AS latitude, p.property_longitude AS longitude, ps.safety_score AS safetyScore, CASE WHEN ps.safety_score IS NULL THEN NULL WHEN ps.safety_score >= 80 THEN 'SAFE' WHEN ps.safety_score >= 60 THEN 'WARNING' ELSE 'DANGER' END AS safetyGrade, ps.cctv_count AS cctvCount, ps.street_lamp_count AS streetlightCount, ps.has_police_station AS hasPoliceStation, p.is_illegal_building AS isIllegalBuilding, CASE WHEN p.is_illegal_building = TRUE THEN '건축물대장 상 무단 증·개축 위반 지정' ELSE '건축물대장 표제부 기준 적법 건물 (무단 증·개축 없음)' END AS illegalReason, CONCAT(p.built_year, '1015') AS useAprDay, '철근콘크리트구조' AS structureName, CASE WHEN p.building_type = 3 THEN '업무시설(오피스텔)' ELSE '공동주택(다세대/연립)' END AS mainPurposeName, '1' AS earthquakeProofYn, COALESCE(p.deal_count, 1) AS dealCount, CASE WHEN b.bookmark_id IS NOT NULL THEN TRUE ELSE FALSE END AS isBookmarked FROM properties p LEFT JOIN property_safety ps ON p.property_id = ps.property_id AND ps.destination_id =
#{destinationId}
-1
LEFT JOIN bookmarks b ON p.property_id = b.property_id
AND b.user_id = #{userId}
WHERE p.property_id = #{propertyId} AND p.del_yn = 'N'

mapper.update:
UPDATE properties
SET property_latitude = #{latitude},
    property_longitude = #{longitude}
WHERE property_id = #{propertyId}

update.foreach:
UPDATE properties
SET property_latitude = #{p.latitude, jdbcType=DECIMAL},
    property_longitude = #{p.longitude, jdbcType=DECIMAL}
WHERE property_id = #{p.propertyId}
